import{_ as t,c as e,o as r,ag as n}from"./chunks/framework.Cycwnjj0.js";const s="/assets/geo-tracking-map-under-geo-location-from-azonpress-dashboard.10LzhM28.webp",d=JSON.parse('{"title":"Geo Location Report","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/geo-location-report.md","filePath":"guide/reports/geo-location-report.md"}'),a={name:"guide/reports/geo-location-report.md"};function i(c,o,g,l,p,h){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="geo-location-report" tabindex="-1">Geo Location Report <a class="header-anchor" href="#geo-location-report" aria-label="Permalink to &quot;Geo Location Report&quot;">​</a></h1><p>In AzonPress, the &quot;<strong>Geo Location</strong>&quot; feature of the <strong>Reports</strong> section allows you to view click reports, track the origin of clicks, and display the information on a Geo Tracking Map for your Amazon Products &amp; Comparison Tables, and Custom Products. You can also see the number of clicks received from each country and filter your report for a specific time range. This article will guide you through how you can view the Geo Location Report.</p><h2 id="geo-location-reports-with-azonpress" tabindex="-1">Geo Location Reports with AzonPress <a class="header-anchor" href="#geo-location-reports-with-azonpress" aria-label="Permalink to &quot;Geo Location Reports with AzonPress&quot;">​</a></h2><p>To learn how you can view the Geo Location Reports in AzonPress, follow the steps with the screenshots below –</p><p><strong>Remember</strong>, <strong>to view</strong> this <strong>GEO Location Report</strong>, first you <strong>need to configure GEO Tracking with Maxmind GEO-IP API Key</strong>. To Configure the Maxmind API Key, you can follow this <a href="/guide/configuring-amazon-api/geo-tracking-targeting-settings.html">Documentation</a>.</p><p>First, go to <strong>Reports</strong> from the <strong>AzonPress Navbar</strong>, click the <strong>Geo Location</strong> option, and get your Geo Location Report for all your Products.</p><p><strong>All the options of Reports are briefly explained below:</strong></p><ol><li>Here, you can Filter click reports based on timeframes like <strong>Year</strong> (ongoing year), <strong>Last Month</strong>, <strong>This Month</strong> (ongoing month), <strong>Last Week</strong>, <strong>Today</strong> (ongoing day), and selecting <strong>All</strong> shows the overall report for the entire time range.</li><li>In this option, you can use the <strong>Date Filter</strong> to view reports from a specific timeline.</li><li>You can also see how many clicks you got from each country by clicking on the <strong>Show Click From Each Country</strong> button.</li><li>With this <strong>Plus</strong> and <strong>Minus</strong> icon, you can zoom out and zoom in on your Geo Tracking Map.</li></ol><p><img src="'+s+'" alt="Geo Tracking Map under Geo Location from AzonPress dashboard"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',11)])])}const m=t(a,[["render",i]]);export{d as __pageData,m as default};
